INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (1, 'msg_whatsapp', 'renovacao', NULL, 'Oi, {nome}! Sua renovação é em {data}: {valor}. PIX: {pix}. Pode me mandar o comprovante? Victor | VFITCOACH', 1),(2, 'msg_whatsapp', 'falta', NULL, 'Oi, {nome}! Senti sua falta nos treinos (última aula em {data}). Está tudo bem? Vamos remarcar? Victor | VFITCOACH', 2),(3, 'msg_whatsapp', 'boas_vindas', NULL, 'Oi, {nome}! Seja bem-vindo(a) à VFITCOACH! Fico feliz em começar essa jornada com você. Victor | VFITCOACH', 3),(4, 'msg_whatsapp', 'reativacao', NULL, 'Oi, {nome}! Faz tempo que não nos falamos. Que tal retomarmos os treinos? Tenho novidades para você. Victor | VFITCOACH', 4),(5, 'msg_whatsapp', 'cobranca', NULL, 'Oi, {nome}, tudo bem? Sua mensalidade de {valor}, vencida em {data}, ainda não constou aqui. Deve ter sido esquecimento, né? Segue o Pix atualizado.', 5),(6, 'msg_whatsapp', 'indicacao', NULL, 'Oi, {nome}! Tá curtindo os treinos? Se você conhece alguém que quer começar, me indica! Quando a pessoa fechar, você ganha {vantagem} 🎁 Victor | VFITCOACH', 6),(7, 'msg_whatsapp', 'dupla', NULL, 'Oi, {nome}! Que tal treinar com um amigo ou amiga? Em dupla o treino rende mais, é mais animado e vocês se cobram um ao outro. Quer trazer alguém? Victor | VFITCOACH', 7),(8, 'msg_whatsapp', 'depoimento', NULL, 'Oi, {nome}! Seu treino comigo tem feito diferença? Você toparia me mandar um depoimento curto (texto ou vídeo)? {link_avaliacao} Obrigado! 🙏 Victor | VFITCOACH', 8),(9, 'msg_dados', 'pix', NULL, '', 1),(10, 'msg_dados', 'link_avaliacao', NULL, '', 2),(11, 'msg_dados', 'vantagem', NULL, 'uma avaliação física grátis', 3),(12, 'msg_dados', 'pix_nome', NULL, '', 4),(13, 'msg_dados', 'pix_cidade', NULL, '', 5),(14, 'msg_dados', 'pix_banco', NULL, '', 6),(15, 'msg_whatsapp', 'upsell', NULL, 'Oi, {nome}! Tenho uma proposta: {titulo}. Inclui: {inclui}. De {valor_normal} por {valor_oferta}/mês{duracao}{depois}.{ate} Quer aproveitar? Victor | VFITCOACH', 9),(16, 'msg_whatsapp', 'cobranca_lembrete', NULL, 'Oi, {nome}! Tudo bem? Passando só pra lembrar que faltam {faltam} dias para o vencimento da sua mensalidade de {valor}, no dia {data}. O Pix está logo abaixo pra facilitar.', 10),(17, 'msg_whatsapp', 'cobranca_hoje', NULL, 'Bom dia, {nome}! Hoje vence a sua mensalidade de {valor}. Consegue dar uma olhadinha? O Pix está logo abaixo.', 11),(18, 'msg_whatsapp', 'cobranca_moderada', NULL, 'Oi, {nome}. Como estão as coisas? Sua mensalidade está vencida desde {data} ({dias} dias). Se aconteceu algum imprevisto, me avisa aqui pra gente dar um jeito.', 12),(19, 'msg_whatsapp', 'cobranca_critica', NULL, '{nome}, sua mensalidade está vencida há mais de um mês (desde {data}). Me chama aqui pra fecharmos um acordo e evitar o bloqueio do serviço.', 13),(20, 'msg_whatsapp', 'cobranca_diferenca', NULL, 'Oi, {nome}! Recebi seu Pix de {pago} em {data}, obrigado! Como ele caiu depois do vencimento, ficou faltando {valor} de multa e juros. Segue o Pix da diferença.', 14),(21, 'cobranca', 'multa', 0.02, NULL, 1),(22, 'cobranca', 'juros_ao_mes', 0.01, NULL, 2),(23, 'taxa_pagamento', 'PIX', 0.0, NULL, 1),(24, 'taxa_pagamento', 'Cartão 1x', 0.0581, NULL, 2),(25, 'taxa_pagamento', 'Cartão 3x', 0.0765, NULL, 3),(26, 'taxa_pagamento', 'Cartão 6x', 0.104, NULL, 4),(27, 'taxa_pagamento', 'Cartão 12x', 0.159, NULL, 5),(28, 'margem_minima', 'Pacote de Aulas', 0.15, NULL, 1),(29, 'margem_minima', 'Mensalidade', 0.15, NULL, 2),(30, 'margem_minima', 'Consultoria Online', 0.2, NULL, 3),(31, 'margem_minima', 'Consultoria Híbrida', 0.22, NULL, 4),(32, 'margem_minima', 'Avaliação Física', 0.2, NULL, 5),(33, 'taxa_cia', '1', 70.76, NULL, 1),(34, 'taxa_cia', '2', 99.69, NULL, 2),(35, 'taxa_cia', '3', 151.47, NULL, 3),(36, 'taxa_cia', 'maximo_pessoas', 3.0, NULL, 4),(37, 'grupo_multiplicador', '1', 1.0, NULL, 1),(38, 'grupo_multiplicador', '2', 1.6, NULL, 2),(39, 'grupo_multiplicador', '3', 2.1, NULL, 3),(40, 'grupo_multiplicador', '4', 2.5, NULL, 4),(